-- Complete dispatch integration is developed here, then promoted to a release
-- migration only after differential and authenticated room tests pass.
create or replace function ml_private.stage3_actions(s jsonb,a integer) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$ declare p jsonb:=s->'players'->a;free boolean:=s->>'phase'='action' and s->'choice'='null'::jsonb and (s->>'active')::int=a and (p->>'hp')::int>0;revival jsonb:='[]';bread jsonb:='[]';cards jsonb:='{}';elbow jsonb:='{}';card text;d jsonb;quote integer;cost jsonb;targets jsonb;converted jsonb;equipment jsonb;member jsonb;cells jsonb;options jsonb;target integer;begin
 for member in select * from ml_private.arr(s->'players') loop if jsonb_array_length(ml_private.stage3_revival_cells(s,(member->>'seat')::int,(s#>>'{classic,farmClosed}')::boolean))>0 then revival:=revival||jsonb_build_array(member->'seat');end if;end loop;
 if free and ml_private.stage3_equipped(s,a,'basic-054') and (s#>>array['stage3','starts',a::text])::int>=(s#>>array['stage3','breadReadyAt',a::text])::int then select coalesce(jsonb_agg(q->'seat' order by ord),'[]') into bread from jsonb_array_elements(s->'players') with ordinality t(q,ord) where (q->>'hp')::int>0 and (q->>'seat')::int<>a;end if;
 for card in select x#>>'{}' from ml_private.arr(p->'hand') x loop d:=ml_private.rule_card(s,card);quote:=case when s#>array['stage3','costLocks',card,'turn']=s#>'{stage3,turn}' then (s#>>array['stage3','costLocks',card,'cost'])::int else null end;cost:=case when d->>'randomCost'='true' and quote is null then 'null'::jsonb else ml_private.stage3_card_cost(s,a,card,quote)->'cost' end;
 if d->>'id'='basic-002' and p->>'character'='character-023' then targets:=ml_private.stage3_elbow_targets(s,a,false);elsif d->>'type'='attack' then targets:=ml_private.targets(s,a,card);elsif d->>'id'='basic-037' then targets:=revival;elsif d->>'id'='basic-016' then select coalesce(jsonb_agg(q->'seat' order by ord),'[]') into targets from jsonb_array_elements(s->'players') with ordinality t(q,ord) where (q->>'hp')::int>0 and (q->>'seat')::int<>a and not ml_private.stage3_mount_blocked(s,a) and ml_private.stage3_empty_entry(ml_private.stage3_board(s),a,q->>'cell',jsonb_build_array(a,q->'seat')) and ml_private.stage3_empty_entry(ml_private.stage3_board(s),(q->>'seat')::int,p->>'cell',jsonb_build_array(a,q->'seat'));else targets:='[]';end if;
 converted:=case when p->>'character'='character-023' then ml_private.stage3_elbow_targets(s,a,true) else '[]'::jsonb end;equipment:=case when d->>'type'='equipment' then ml_private.stage3_equipment_options(s,a,card) else 'null'::jsonb end;
  cards:=cards||jsonb_build_object(card,jsonb_build_object('cost',cost,'needsQuote',coalesce(d->>'randomCost'='true' and quote is null,false),'targets',targets,'convertTargets',converted,'equipment',equipment,'blocked',s#>array['stage3','breadBlocked',a::text]));end loop;
 if p->>'character'='character-023' then for target in select (x#>>'{}')::int from ml_private.arr(ml_private.stage3_elbow_targets(s,a,false)) x loop cells:=ml_private.stage3_elbow_cells(ml_private.stage3_board(s),a,target);select coalesce(jsonb_object_agg(direction,cell),'{}') into options from (select direction,ml_private.stage3_direction_cell(s#>>array['players',target::text,'cell'],direction) cell from unnest(array['up','right','down','left']) direction) q where cell is not null and cells ? cell;elbow:=jsonb_set(elbow,array[target::text],options);end loop;end if;
 return jsonb_build_object('elbowPush',elbow,'jj',free and p->>'character'='character-003' and s#>>array['stage3','jjUsed',a::text]<>'true','breadTargets',bread,'revivalTargets',revival,'cards',cards,'movementBlocked',ml_private.stage3_mount_blocked(s,a),'moveCost',case when ml_private.stage3_equipped(s,a,'basic-071') then 0 else ml_private.stage3_fixed_cost(s,a,ml_private.location_basic_cost(s->>'version',p->>'cell')) end,'locations',jsonb_build_object('ship',ml_private.stage3_locations(s,a,'ship'),'commute',ml_private.stage3_locations(s,a,'commute')),'directionRequired',p->>'character'='character-040','basicMovesRemaining',greatest(0,case when s#>>array['stage3','doubleMove',a::text]='true' then 2 else 1 end-(s#>>array['stage3','basicUsed',a::text])::int));
end $$;
create or replace function ml_private.public_view(s jsonb,viewer integer) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$ declare v jsonb:=ml_private.public_view_before_stage3(s,viewer);r jsonb:=s->'stage3';safe jsonb;begin
 if s->>'version'<>'web-v0.1.6' then return v;end if;select jsonb_object_agg(key,value) into safe from jsonb_each(r) where key in ('turn','equipment','basicUsed','breadBlocked','breadReadyAt','jjFree','jjExposed','horseLocks','combos');
 v:=(v-'cardStack'-'stage3')||jsonb_build_object('stage3',safe);return jsonb_set(v,'{actions,stage3}',ml_private.stage3_actions(s,viewer));
end $$;
create or replace function ml_private.dispatch(previous jsonb,cmd jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare s jsonb:=previous;a integer;typ text:=cmd->>'type';p jsonb;v jsonb;cell text;cost integer;roll integer;steps integer;direction text;deadline double precision;guard integer:=0;changed boolean:=false;begin
 if previous->>'version'<>'web-v0.1.6' then return ml_private.dispatch_before_stage3(previous,cmd,at);end if;
 perform ml_private.need(jsonb_typeof(cmd)='object','命令必须为对象');perform ml_private.need(jsonb_typeof(cmd->'actor')='number' and (cmd->>'actor')::numeric=trunc((cmd->>'actor')::numeric) and (cmd->>'actor')::int between 0 and 3 and jsonb_typeof(cmd->'revision')='number' and (cmd->>'revision')::numeric=trunc((cmd->>'revision')::numeric) and (cmd->>'revision')::bigint>=0,'座位/命令版本必须为有效整数');a:=(cmd->>'actor')::int;
 perform ml_private.need(typ in ('play','move','step','stop','end','choose','tick','location','skill'),'未知命令');
 if typ='play' then perform ml_private.need(jsonb_typeof(cmd->'card')='string' and jsonb_typeof(cmd->'targets')='array' and not exists(select 1 from ml_private.arr(cmd->'targets') x where jsonb_typeof(x)<>'number' or (x#>>'{}')::numeric<>trunc((x#>>'{}')::numeric) or (x#>>'{}')::int not between 0 and 3),'出牌/目标输入无效');perform ml_private.need((not (cmd ? 'as') or cmd->>'as'='elbow') and (not (cmd ? 'replacement') or jsonb_typeof(cmd->'replacement')='string'),'转换或替换输入无效');end if;
 if typ in ('move','play') and cmd ? 'direction' then perform ml_private.need(cmd->>'direction' in ('up','right','down','left'),'方向输入无效');end if;
 if typ='skill' then perform ml_private.need(cmd->>'kind' in ('jj','bread','revival-quote') and (not (cmd ? 'target') or jsonb_typeof(cmd->'target')='number' and (cmd->>'target')::numeric=trunc((cmd->>'target')::numeric) and (cmd->>'target')::int between 0 and 3) and (not (cmd ? 'card') or jsonb_typeof(cmd->'card')='string'),'技能输入无效');end if;
 if typ='location' then perform ml_private.need(cmd->>'kind' in ('ship','commute') and jsonb_typeof(cmd->'cell')='string','地点动作输入无效');end if;
 if typ='step' then perform ml_private.need(jsonb_typeof(cmd->'path')='array' and not exists(select 1 from ml_private.arr(cmd->'path') x where jsonb_typeof(x)<>'string'),'路径必须为格子数组');end if;
 if typ='choose' then
 perform ml_private.need(jsonb_typeof(cmd->'choice')='number' and (cmd->>'choice')::numeric=trunc((cmd->>'choice')::numeric) and (cmd->>'choice')::bigint>0,'选择编号必须为正整数');
 perform ml_private.need(not (cmd ? 'accept') or jsonb_typeof(cmd->'accept')='boolean','发动选项必须为布尔值');perform ml_private.need(not (cmd ? 'card') or jsonb_typeof(cmd->'card') in ('string','null'),'响应牌输入无效');perform ml_private.need(not (cmd ? 'cell') or jsonb_typeof(cmd->'cell') in ('string','null'),'传送格输入无效');
 perform ml_private.need(not (cmd ? 'cards') or jsonb_typeof(cmd->'cards')='array' and not exists(select 1 from ml_private.arr(cmd->'cards') x where jsonb_typeof(x)<>'string'),'弃牌必须为实体牌数组');
 perform ml_private.need((not (cmd ? 'target') or jsonb_typeof(cmd->'target')='number' and (cmd->>'target')::numeric=trunc((cmd->>'target')::numeric) and (cmd->>'target')::int between 0 and 3) and (not (cmd ? 'action') or cmd->>'action' in ('draw','steal')),'技能选择输入无效');end if;
 perform ml_private.need(at>=(s->>'time')::double precision and at<'Infinity'::double precision,'时钟必须单调');perform ml_private.need(cmd->'revision'=s->'revision','命令版本过期');perform ml_private.need(jsonb_typeof(cmd->'id')='string' and length(cmd->>'id')>0 and not (s->'seen' ? (cmd->>'id')),'重复命令');perform ml_private.need(s->>'phase'<>'over','对局已经结束');
 if typ='tick' then while s->>'phase'<>'over' loop deadline:=coalesce((s#>>'{choice,deadline}')::double precision,(s#>>'{clock,since}')::double precision+(s#>>'{clock,remaining}')::double precision);exit when deadline is null or deadline>at;exit when guard>=999;guard:=guard+1;s:=ml_private.expire(s,deadline);changed:=true;end loop;if not changed then return jsonb_build_object('state',previous,'ok',true);end if;
 else perform ml_private.need(not (case when s->'choice'<>'null'::jsonb then at>=(s#>>'{choice,deadline}')::double precision else s#>'{clock,since}'<>'null'::jsonb and ml_private.budget(s,at)=0 end),'命令已超时，请先处理时钟事件');
 if typ='choose' then perform ml_private.need(s->'choice'<>'null'::jsonb,'当前没有选择窗口');s:=ml_private.choose(s,cmd,at);
 else p:=s->'players'->a;perform ml_private.need(a=(s->>'active')::int and (p->>'hp')::int>0,'只有当前存活行动者可操作');perform ml_private.need(s->'choice'='null'::jsonb,'请先完成当前选择');
 if typ='step' then perform ml_private.need(s->>'phase'='moving' and s->'movement'<>'null'::jsonb,'尚未开始移动');perform ml_private.need(jsonb_array_length(cmd->'path')>0,'移动路径不能为空');s:=ml_private.classic_walk(s,cmd->'path',at);
 elsif typ='stop' then perform ml_private.need(s->'movement'<>'null'::jsonb,'尚未开始移动');perform ml_private.need(not ml_private.occupied(s,p->>'cell',a),'不能停在占用格');s:=ml_private.settle_movement(s);s:=s||jsonb_build_object('movement',null,'phase','action');s:=ml_private.emit(s,'move','主动结束移动，未用额度作废');
 elsif typ='end' then perform ml_private.need(s->'movement'='null'::jsonb or not ml_private.occupied(s,p->>'cell',a),'不能在占用格结束行动，请先离开');s:=ml_private.end_turn(s,at);
 else perform ml_private.need(s->>'phase'='action','请先完成移动');
 if typ='location' then cell:=cmd->>'cell';perform ml_private.need(ml_private.stage3_locations(s,a,cmd->>'kind') ? cell,'地点传送当前不可用或落点不合法');if cmd->>'kind'='ship' then s:=jsonb_set(s,'{classic,shipUsed}',(s#>'{classic,shipUsed}')||jsonb_build_array(a));else s:=jsonb_set(s,array['players',a::text,'ap'],'0');end if;s:=ml_private.stage3_relocate(s,a,cell,true);s:=jsonb_set(s,'{queue}',(s->'queue')||(s->'_relocationTasks'));s:=s-'_relocationTasks';s:=ml_private.emit(s,'teleport',ml_private.name(s,a)||' '||case when cmd->>'kind'='ship' then '飞船' else '通校' end||'至'||cell);
 elsif typ='move' then
 perform ml_private.need(p->>'moved'='false','本个人回合已使用基础移动');perform ml_private.need(not ml_private.stage3_mount_blocked(s,a),'小白马：有坐骑者暂时不能主动位移');cost:=case when ml_private.stage3_equipped(s,a,'basic-071') then 0 else ml_private.stage3_fixed_cost(s,a,ml_private.location_basic_cost(s->>'version',p->>'cell')) end;perform ml_private.need((p->>'ap')::int>=cost,'移动需要1AP');
 if p->>'character'='character-040' then perform ml_private.need(cmd ? 'direction','请先声明移动方向');s:=ml_private.die(s,'西帝汶方向');direction:=ml_private.stage3_west_direction(cmd->>'direction',(s->>'_roll')::int);s:=s-'_roll';end if;
 s:=ml_private.die(s,'基础移动');roll:=(s->>'_roll')::int;s:=s-'_roll';steps:=case when s#>>array['stage3','doubleMove',a::text]='true' and ml_private.stage3_equipped(s,a,'basic-066') then roll else ceil(roll::numeric/2)::int end;s:=jsonb_set(s,array['stage3','basicUsed',a::text],to_jsonb((s#>>array['stage3','basicUsed',a::text])::int+1));s:=jsonb_set(s,array['players',a::text,'moved'],to_jsonb((s#>>array['stage3','basicUsed',a::text])::int>=case when s#>>array['stage3','doubleMove',a::text]='true' then 2 else 1 end));
 s:=s||jsonb_build_object('movement',jsonb_build_object('remaining',steps,'lastEmpty',p->'cell','origin',p->'cell','path',jsonb_build_array(p->'cell'),'costDue',cost>0,'carry',ml_private.stage3_carry_candidates(s,a,p->>'cell'))||case when direction is null then '{}'::jsonb else jsonb_build_object('direction',direction) end,'phase','moving');s:=ml_private.emit(s,'cost',ml_private.name(s,a)||case when cost=0 then ' 免费移动' else ' 移动结束扣费' end||'，获得'||steps||'步');
 elsif typ='skill' then s:=ml_private.stage3_skill(s,cmd,at);
 elsif typ='play' then s:=ml_private.stage3_play(s,cmd,at);else raise exception '未知命令';end if;end if;end if;end if;
 s:=ml_private.pump(s,at);s:=s||jsonb_build_object('seen',(s->'seen')||jsonb_build_array(cmd->'id'),'revision',(s->>'revision')::int+1,'time',at);perform ml_private.validate(s);return jsonb_build_object('state',s,'ok',true);
 exception when others then return jsonb_build_object('state',previous,'ok',false,'error',sqlerrm);
end $$;
create or replace function ml_private.stage3_skill(s jsonb,cmd jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare a integer:=(cmd->>'actor')::int;p jsonb:=s->'players'->a;kind text:=cmd->>'kind';target integer:=(cmd->>'target')::int;gear text;effect jsonb;cost integer;prior jsonb;card text:=cmd->>'card';begin
 if kind='jj' then perform ml_private.need(p->>'character'='character-003' and s#>>array['stage3','jjUsed',a::text]<>'true','懒得喷本回合已使用或角色不符');s:=jsonb_set(s,array['stage3','jjUsed',a::text],'true');s:=jsonb_set(s,array['stage3','jjFree',a::text],'true');s:=jsonb_set(s,array['stage3','jjExposed',a::text],'true');return ml_private.emit(s,'skill','S'||(a+1)||' 懒得喷：固定费用免费，暴露至下次个人回合开始');end if;
 if kind='bread' then
 select c#>>'{}' into gear from ml_private.arr(s#>array['stage3','equipment',a::text]) c where split_part(c#>>'{}','#',1)='basic-054' limit 1;effect:=s#>array['stage3','equipmentSources',gear];perform ml_private.need(gear is not null and effect is not null and (s#>>array['stage3','starts',a::text])::int>=(s#>>array['stage3','breadReadyAt',a::text])::int and target<>a and ml_private.stage3_alive(s,target),'面包技能或目标不可用');cost:=ml_private.stage3_fixed_cost(s,a,2);perform ml_private.need((p->>'ap')::int>=cost,'面包技能需要2AP');s:=jsonb_set(s,array['players',a::text,'ap'],to_jsonb((p->>'ap')::int-cost));effect:=effect||jsonb_build_object('origin','equipment');if s#>>array['stage3','jjFree',a::text]='true' then effect:=jsonb_set(effect,'{roleModifiers}',(effect->'roleModifiers')||jsonb_build_array(jsonb_build_object('actor',a,'kind','cost')));end if;
 prior:=s#>array['stage3','breadPending',target::text];s:=ml_private.stage3_bread(s,a,target);if not ml_private.stage3_card_allowed(s,target,'basic-054',effect) then s:=jsonb_set(s,array['stage3','breadPending',target::text],prior);end if;return ml_private.emit(s,'skill','S'||(a+1)||' 面包黏稠，支付'||cost||'AP');end if;
 perform ml_private.need(split_part(card,'#',1)='basic-037' and jsonb_array_length(ml_private.stage3_revival_cells(s,target,(s#>>'{classic,farmClosed}')::boolean))>0,'当前没有合法紫檀木复活目标');
 if s#>array['stage3','costLocks',card,'turn']=s#>'{stage3,turn}' then cost:=(s#>>array['stage3','costLocks',card,'cost'])::int;else s:=ml_private.die(s,'紫檀木费用');cost:=(s->>'_roll')::int;s:=s-'_roll';s:=ml_private.stage3_lock_cost(s,a,card,cost);s:=s-'_cost';end if;return ml_private.select_choice(s,'revival-confirm',a,at,jsonb_build_object('source',target,'data',jsonb_build_object('card',card,'cost',cost)));
end $$;
create or replace function ml_private.choose(s jsonb,cmd jsonb,at double precision,timeout boolean default false) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare c jsonb:=s->'choice';kind text:=c->>'kind';a integer:=(c->>'actor')::int;target integer:=(cmd->>'target')::int;card text:=cmd->>'card';cell text:=cmd->>'cell';pending jsonb;quoted jsonb;result jsonb;cards jsonb;cells jsonb;amount integer;snapshot jsonb;tasks jsonb:='[]';old text;begin
 if s->>'version'<>'web-v0.1.6' then return ml_private.choose_before_stage3(s,cmd,at,timeout);end if;perform ml_private.need(cmd->'choice'=c->'id','选择窗口已过期');perform ml_private.need((cmd->>'actor')::int=a,'请交给待选择的座位操作');
 case kind
 when 'easy' then
 amount:=1;if cmd->>'accept'='true' and not timeout and at<(c->>'deadline')::double precision then s:=ml_private.die(s,'easy 太简单了');amount:=(s->>'_roll')::int;s:=s-'_roll';end if;s:=ml_private.stage3_counter_card(s,a,cmd->>'accept'='true' and not timeout,at,amount);result:=s->'_counterResult';s:=s-'_counterResult';s:=ml_private.emit(s,'skill',case when result->>'attempted'='true' then 'S'||(a+1)||' 反制支付1AP，'||case when result->>'cancelled'='true' then '整牌失效' else '判定失败' end else 'S'||(a+1)||' 结束反制' end);if result->>'done'<>'true' then return s;end if;
 when 'response' then if card is not null and card<>'' then perform ml_private.need(c->'cards' ? card,'响应牌不可用');pending:=s#>'{cardStack,stack,-1}';quoted:=ml_private.stage3_card_cost(s,a,card);s:=jsonb_set(s,array['players',a::text,'ap'],to_jsonb((s#>>array['players',a::text,'ap'])::int-(quoted->>'cost')::int));s:=jsonb_set(s,array['players',a::text,'hand'],(s#>array['players',a::text,'hand'])-card);s:=jsonb_set(s,'{resolving}',(s->'resolving')||jsonb_build_array(card));s:=ml_private.stage3_begin_card(s,a,card,split_part(card,'#',1),'[]',quoted->'effect',at,(pending->>'serial')::int);pending:=s#>'{cardStack,stack,-1}';s:=ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('counter',jsonb_build_object('serial',pending->'serial')),ml_private.stage3_task('continue',jsonb_build_object('serial',pending->'serial'))));s:=ml_private.emit(s,'response','S'||(a+1)||' 使用'||(ml_private.rule_card(s,card)->>'name')||'，支付'||(quoted->>'cost')||'AP');end if;
 when 'xiao-overflow' then
 if timeout then select coalesce(jsonb_agg(x order by x),'[]') into cards from (select x from ml_private.arr(s#>array['players',a::text,'hand']) x order by x limit (c->>'count')::int) q;else cards:=coalesce(cmd->'cards','[]');end if;s:=ml_private.stage3_transfer_overflow(s,a,(c->>'source')::int,cards);s:=ml_private.emit(s,'transfer','S'||(a+1)||' 超限'||jsonb_array_length(cards)||'张交给S'||((c->>'source')::int+1));
 when 'qb-pursuit' then if cmd->>'accept'='true' and ml_private.stage3_alive(s,(c->>'source')::int) then s:=ml_private.die(s,'QB 纯菜');target:=case when (s->>'_roll')::int>=3 then (c->>'source')::int else a end;s:=s-'_roll';s:=ml_private.stage3_damage(s,jsonb_build_array(jsonb_build_object('target',target,'amount',1,'source',a,'category','response')),false,true);s:=ml_private.stage3_prepend(s,s->'_triggers');s:=s-'_triggers';end if;
 when 'east-start' then if cmd ? 'action' then perform ml_private.need(ml_private.stage3_east_targets(s,a,cmd->>'action') @> jsonb_build_array(target),'领袖风范目标不合法');if cmd->>'action'='draw' then s:=ml_private.draw(s,a,1);s:=ml_private.draw(s,target,1);else cards:=s#>array['players',target::text,'hand'];s:=ml_private.int(s,jsonb_array_length(cards));amount:=(s->>'_int')::int;s:=s-'_int';s:=jsonb_set(s,array['players',a::text,'hand'],(s#>array['players',a::text,'hand'])||jsonb_build_array(cards->amount));s:=jsonb_set(s,array['players',target::text,'hand'],cards-amount);s:=ml_private.emit(s,'transfer','S'||(a+1)||' 从S'||(target+1)||' 随机拿1张');end if;end if;
 when 'xie-ledger' then if target is not null then perform ml_private.need(c->'targets' @> jsonb_build_array(target) and ml_private.stage3_alive(s,target),'阎王薄目标不合法');s:=ml_private.damage(s,jsonb_build_array(jsonb_build_object('target',target,'amount',1,'source',a,'category','response')));s:=ml_private.stage3_prepend(s,s->'_triggers');s:=s-'_triggers';end if;
 when 'elbow-push' then target:=(c->>'source')::int;cells:=ml_private.stage3_elbow_cells(ml_private.stage3_board(s),a,target);if timeout then cell:=cells->>0;end if;if cell is null then perform ml_private.need(jsonb_array_length(cells)=0,'请选择一个撞飞方向');else perform ml_private.need(cells ? cell,'撞飞落点已失效');s:=ml_private.stage3_relocate(s,target,cell,false);tasks:=s->'_relocationTasks';s:=s-'_relocationTasks';s:=ml_private.stage3_relocate(s,a,c#>>'{data,origin}',true);tasks:=tasks||(s->'_relocationTasks');s:=ml_private.stage3_prepend(s-'_relocationTasks',tasks);end if;
 when 'west-carry' then if target is not null then select x into snapshot from ml_private.arr(c->'data') x where (x->>'actor')::int=target;perform ml_private.need(snapshot is not null and cell is not null and ml_private.stage3_carry_destinations(ml_private.stage3_board(s),a,target,snapshot->>'origin') ? cell,'同行对象或落点不合法');s:=ml_private.stage3_relocate(s,target,cell,false,false);s:=ml_private.stage3_prepend(s,s->'_relocationTasks');s:=s-'_relocationTasks';end if;
 when 'equipment-loss' then old:=split_part(c#>>'{data,card}','#',1);if old='basic-054' and cmd->>'accept'='true' then s:=ml_private.heal(s,a,2);elsif old='basic-063' and cell is not null then perform ml_private.need(c->'cells' ? cell,'山洞落点不合法');s:=ml_private.stage3_relocate(s,a,cell,true);s:=ml_private.stage3_prepend(s,s->'_relocationTasks');s:=s-'_relocationTasks';end if;
 when 'revival-confirm' then if cmd->>'accept'='true' then s:=ml_private.stage3_play(s,jsonb_build_object('type','play','id',cmd->'id','revision',cmd->'revision','actor',a,'card',c#>'{data,card}','targets',jsonb_build_array(c->'source')),at);end if;
 when 'teleport' then if cell is not null then perform ml_private.need(c->'cells' ? cell and ml_private.teleport_cells(s,a) ? cell,'传送须为距离≤3的空陆地');s:=ml_private.stage3_relocate(s,a,cell,true);s:=ml_private.stage3_prepend(s,s->'_relocationTasks');s:=s-'_relocationTasks';s:=jsonb_set(s,array['players',a::text,'skillUsed'],'true');s:=ml_private.emit(s,'teleport',ml_private.name(s,a)||' 传送至'||cell||case when s->'safe' ? cell then '' else '（毒圈外）' end);end if;
 when 'lemon-support' then if cmd->>'accept'='true' then perform ml_private.need((s#>>array['players',a::text,'ap'])::int>=1 and s#>>array['players',a::text,'skillUsed']='false','支援不可用');s:=jsonb_set(s,array['players',a::text,'ap'],to_jsonb((s#>>array['players',a::text,'ap'])::int-1));s:=jsonb_set(s,array['players',a::text,'skillUsed'],'true');for target in 0..3 loop if ml_private.stage3_alive(s,target) and (target=a or (s->>'mode'='team' and s#>array['players',target::text,'team']=s#>array['players',a::text,'team'])) and ml_private.character_effect_allowed(jsonb_build_object('origin','role-active','actor',a,'roleModifiers','[]'::jsonb),target,s#>>array['players',target::text,'character']) then s:=ml_private.draw(s,target,1);end if;end loop;s:=ml_private.emit(s,'skill',ml_private.name(s,a)||' 支援，支付1AP');end if;
 else s:=ml_private.choose_before_stage3(s,cmd,at,timeout);if s->'choice'='null'::jsonb and jsonb_array_length(s->'queue')=0 and s->>'phase'='resolving' and s->'movement'='null'::jsonb and ml_private.stage3_alive(s,(s->>'active')::int) then s:=jsonb_set(s,'{phase}','"action"');s:=ml_private.resume(s,at);end if;return s;
 end case;
 if timeout then s:=ml_private.emit(s,'timeout',ml_private.name(s,a)||' 选择超时：'||kind);end if;s:=s||jsonb_build_object('choice',null,'phase','resolving');s:=ml_private.pump(s,at);if s->'choice'='null'::jsonb and jsonb_array_length(s->'queue')=0 and s->>'phase'='resolving' and s->'movement'='null'::jsonb and ml_private.stage3_alive(s,(s->>'active')::int) then s:=jsonb_set(s,'{phase}','"action"');s:=ml_private.resume(s,at);end if;return s;
end $$;
create or replace function ml_private.stage3_alive(s jsonb,a integer) returns boolean language sql immutable as $$ select coalesce((s#>>array['players',a::text,'hp'])::int>0,false) $$;
create or replace function ml_private.stage3_available_targets(s jsonb,pending jsonb) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$ select coalesce(jsonb_agg(t order by ord),'[]') from jsonb_array_elements(pending->'targets') with ordinality x(t,ord) where ml_private.stage3_alive(s,(t#>>'{}')::int) and not (pending->'cancelled' @> jsonb_build_array(t)) and ml_private.stage3_card_allowed(s,(t#>>'{}')::int,pending->>'definition',pending->'effect') and ml_private.location_effect_allowed('web-v0.1.5',s#>>array['players',t#>>'{}','cell'],pending->>'definition') $$;
create or replace function ml_private.stage3_responses(s jsonb,a integer,pending jsonb) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$ select coalesce(jsonb_agg(card order by ord),'[]') from jsonb_array_elements(s#>array['players',a::text,'hand']) with ordinality x(card,ord) where ((split_part(card#>>'{}','#',1)='basic-001' and pending->>'definition'<>'basic-009') or (split_part(card#>>'{}','#',1)='basic-002' and pending->>'definition'='basic-008')) and (s#>>array['players',a::text,'ap'])::int>=(ml_private.stage3_card_cost(s,a,card#>>'{}')->>'cost')::int $$;
create or replace function ml_private.stage3_handle_task(s jsonb,t jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare action text:=t->>'action';a integer:=coalesce((t->>'actor')::int,(s->>'active')::int);target integer;origin text;targets jsonb;cells jsonb;valid jsonb;pending jsonb;d jsonb;after_tasks jsonb:='[]';cards jsonb;hits jsonb:='[]';roll integer:=0;paid integer;amount integer;before_hp jsonb;xie integer;ledger jsonb:='[]';old text;old_source jsonb;closed jsonb;idx text;gained integer;begin
 if action='east' then targets:=ml_private.stage3_east_targets(s,a,'draw');if jsonb_array_length(targets)>0 then s:=ml_private.select_choice(s,'east-start',a,at,jsonb_build_object('targets',targets));end if;return s;end if;
 if action='elbow-hit' then target:=(t->>'target')::int;if not ml_private.stage3_alive(s,a) or not ml_private.stage3_alive(s,target) then return s;end if;origin:=s#>>array['players',target::text,'cell'];s:=ml_private.damage(s,jsonb_build_array(jsonb_build_object('target',target,'amount',1,'source',a,'category','attack')));s:=ml_private.stage3_prepend(s,(s->'_triggers')||jsonb_build_array(ml_private.stage3_task('elbow-push',jsonb_build_object('actor',a,'target',target,'data',jsonb_strip_nulls(jsonb_build_object('origin',origin,'direction',s#>'{cardStack,stack,-1,pushDirection}'))))));return s-'_triggers';end if;
 if action='qb' then target:=(t->>'target')::int;if ml_private.stage3_alive(s,a) and ml_private.stage3_alive(s,target) and ml_private.character_effect_allowed(jsonb_build_object('origin','role-active','actor',a,'roleModifiers','[]'::jsonb),target,s#>>array['players',target::text,'character']) then s:=ml_private.select_choice(s,'qb-pursuit',a,at,jsonb_build_object('source',target));end if;return s;end if;
 if action='ledger' then select coalesce(jsonb_agg(x order by ord),'[]') into targets from jsonb_array_elements(t->'data') with ordinality q(x,ord) where ml_private.stage3_alive(s,(x#>>'{}')::int);if ml_private.stage3_alive(s,a) and jsonb_array_length(targets)>0 then s:=ml_private.select_choice(s,'xie-ledger',a,at,jsonb_build_object('targets',targets));end if;return s;end if;
 if action='carry' then select coalesce(jsonb_agg(x order by ord),'[]') into valid from jsonb_array_elements(t->'data') with ordinality q(x,ord) where jsonb_array_length(ml_private.stage3_carry_destinations(ml_private.stage3_board(s),a,(x->>'actor')::int,x->>'origin'))>0;if ml_private.stage3_alive(s,a) and jsonb_array_length(valid)>0 then select jsonb_agg(x->'actor' order by ord) into targets from jsonb_array_elements(valid) with ordinality q(x,ord);s:=ml_private.select_choice(s,'west-carry',a,at,jsonb_build_object('targets',targets,'data',valid,'options',(select jsonb_object_agg(x->>'actor',ml_private.stage3_carry_destinations(ml_private.stage3_board(s),a,(x->>'actor')::int,x->>'origin')) from ml_private.arr(valid) x)));end if;return s;end if;
 if action='elbow-push' then target:=(t->>'target')::int;origin:=t#>>'{data,origin}';if not ml_private.stage3_alive(s,a) then return s;end if;if not ml_private.stage3_alive(s,target) then if ml_private.stage3_empty_entry(ml_private.stage3_board(s),a,origin) then s:=ml_private.stage3_relocate(s,a,origin,true);s:=ml_private.stage3_prepend(s,s->'_relocationTasks');s:=s-'_relocationTasks';end if;return s;end if;cells:=ml_private.stage3_elbow_cells(ml_private.stage3_board(s),a,target);if jsonb_array_length(cells)>0 and t#>>'{data,direction}' is not null and cells ? ml_private.stage3_direction_cell(s#>>array['players',target::text,'cell'],t#>>'{data,direction}') then origin:=s#>>array['players',target::text,'cell'];s:=ml_private.stage3_relocate(s,target,ml_private.stage3_direction_cell(origin,t#>>'{data,direction}'),false);after_tasks:=s->'_relocationTasks';s:=s-'_relocationTasks';s:=ml_private.stage3_relocate(s,a,origin,true);s:=ml_private.stage3_prepend(s,after_tasks||(s->'_relocationTasks'));return s-'_relocationTasks';end if;if jsonb_array_length(cells)>0 then s:=ml_private.select_choice(s,'elbow-push',a,at,jsonb_build_object('source',target,'cells',cells,'data',jsonb_build_object('origin',s#>array['players',target::text,'cell'])));end if;return s;end if;
 pending:=s#>'{cardStack,stack,-1}';perform ml_private.need(pending is not null,'没有待结算卡牌');perform ml_private.need(not (t ? 'serial') or t->'serial'=pending->'serial','卡牌结算编号过期');a:=(pending->>'actor')::int;idx:=(jsonb_array_length(s#>'{cardStack,stack}')-1)::text;d:=ml_private.stage3_content()#>array['cards',pending->>'definition'];
 if action='equip-install' then if ml_private.stage3_alive(s,a) then s:=jsonb_set(s,array['stage3','equipment',a::text],(s#>array['stage3','equipment',a::text])||jsonb_build_array(pending->'card'));s:=jsonb_set(s,array['stage3','equipmentSources',pending->>'card'],pending->'effect');s:=jsonb_set(s,'{resolving}',(s->'resolving')-(pending->>'card'));s:=jsonb_set(s,array['cardStack','stack',idx,'installed'],'true');valid:=to_jsonb(coalesce(ml_private.stage3_equipped(s,a,'basic-066') and s#>array['stage3','previousBasic',a::text]='false'::jsonb,false));s:=jsonb_set(s,array['stage3','doubleMove',a::text],valid);s:=jsonb_set(s,array['players',a::text,'moved'],to_jsonb((s#>>array['stage3','basicUsed',a::text])::int>=case when valid='true'::jsonb then 2 else 1 end));s:=ml_private.emit(s,'equip','S'||(a+1)||' 装备'||(d->>'name'));end if;return s;end if;
 if action='counter' then if pending->'counter'<>'null'::jsonb then s:=ml_private.select_choice(s,'easy',(pending#>>'{counter,actor}')::int,at,jsonb_build_object('deadline',pending#>'{counter,deadline}','data',jsonb_build_object('serial',pending->'serial')));end if;return s;end if;
 if action='continue' then
 if pending->>'countered'='true' or pending->'responseTo'<>'null'::jsonb then return ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('cleanup',jsonb_build_object('serial',pending->'serial'))));end if;
 if d->>'type'='attack' or pending->>'definition'='basic-002' then s:=jsonb_set(s,'{attack}',jsonb_build_object('actor',pending->'actor','card',pending->'card','targets',pending->'targets','cancelled',pending->'cancelled','elbows',pending->'elbows'));targets:=ml_private.stage3_available_targets(s,pending);select coalesce(jsonb_agg(ml_private.stage3_task('response',jsonb_build_object('actor',x,'serial',pending->'serial')) order by ord),'[]') into after_tasks from jsonb_array_elements(s->'order') with ordinality q(x,ord) where targets @> jsonb_build_array(x);end if;return ml_private.stage3_prepend(s,after_tasks||jsonb_build_array(ml_private.stage3_task('effect',jsonb_build_object('serial',pending->'serial'))));end if;
 if action='response' then target:=(t->>'actor')::int;if ml_private.stage3_available_targets(s,pending) @> jsonb_build_array(target) then cards:=ml_private.stage3_responses(s,target,pending);if jsonb_array_length(cards)>0 then s:=ml_private.select_choice(s,'response',target,at,jsonb_build_object('cards',cards,'data',jsonb_build_object('serial',pending->'serial')));end if;end if;return s;end if;
 if action='cleanup' then s:=ml_private.stage3_close_card(s);closed:=s->'_closed';s:=s-'_closed';if closed->>'installed'='true' then s:=jsonb_set(s,'{discard}',(s->'discard')-(closed->>'card'));end if;
 if jsonb_array_length(s#>'{cardStack,stack}')>0 then pending:=s#>'{cardStack,stack,-1}';return jsonb_set(s,'{attack}',jsonb_build_object('actor',pending->'actor','card',pending->'card','targets',pending->'targets','cancelled',pending->'cancelled','elbows',pending->'elbows'));end if;s:=jsonb_set(s,'{attack}','null');s:=ml_private.finish(s,false,at);if s->>'phase'<>'over' then if ml_private.stage3_alive(s,(s->>'active')::int) then s:=jsonb_set(s,'{phase}','"action"');else s:=ml_private.stage3_prepend(s,jsonb_build_array(jsonb_build_object('kind','next')));end if;end if;return s;end if;
 perform ml_private.need(action='effect','未知阶段三结算任务');s:=ml_private.stage3_record_combo(s,a,pending->>'definition');targets:=ml_private.stage3_available_targets(s,pending);
 if pending->>'definition'='basic-002' then select coalesce(jsonb_agg(ml_private.stage3_task('elbow-hit',jsonb_build_object('actor',a,'target',x)) order by ord),'[]') into after_tasks from jsonb_array_elements(targets) with ordinality q(x,ord);
 elsif d->>'type'='attack' then
 select jsonb_agg(member->'hp' order by ord) into before_hp from jsonb_array_elements(s->'players') with ordinality q(member,ord);select (member->>'seat')::int into xie from ml_private.arr(s->'players') member where (member->>'hp')::int>0 and member->>'character'='character-044' limit 1;if xie is not null and pending->>'definition'='basic-010' then ledger:=ml_private.stage3_ledger_candidates(s,xie,a,targets);end if;
 if jsonb_array_length(targets)>0 and pending->>'definition' in ('basic-006','basic-009') then s:=ml_private.die(s,d->>'name');roll:=(s->>'_roll')::int;s:=s-'_roll';end if;
 for target in select (x#>>'{}')::int from ml_private.arr(targets) x loop
 if d ? 'power' then paid:=least((s#>>array['players',target::text,'ap'])::int,(d->>'power')::int);s:=jsonb_set(s,array['players',target::text,'ap'],to_jsonb((s#>>array['players',target::text,'ap'])::int-paid));s:=ml_private.emit(s,'ap','S'||(target+1)||' 被扣'||paid||'AP → '||(s#>>array['players',target::text,'ap']));if paid<(d->>'power')::int then hits:=hits||jsonb_build_array(jsonb_build_object('target',target,'amount',(d->>'power')::int-paid,'source',a,'category','attack'));end if;
 elsif pending->>'definition'='basic-008' then amount:=(s#>>array['players',target::text,'ap'])::int;if amount=0 then hits:=hits||jsonb_build_array(jsonb_build_object('target',target,'amount',1,'source',a,'category','attack'));else s:=jsonb_set(s,array['players',target::text,'ap'],'0');s:=ml_private.stage3_gain_ap(s,a,amount);s:=ml_private.emit(s,'ap','S'||(a+1)||' 头锤吸收全部'||amount||'AP，晓虫收取'||(s#>>'{_gain,taken}')||'AP');s:=s-'_gain';end if;
 else
 if pending->>'definition'='basic-010' then s:=ml_private.die(s,'S'||(target+1)||' 猴子游戏');valid:=to_jsonb((s->>'_roll')::int%2=1);s:=s-'_roll';else valid:=to_jsonb(roll>=4);end if;if valid='true'::jsonb then hits:=hits||jsonb_build_array(jsonb_build_object('target',target,'amount',1,'source',a,'category','attack'));end if;end if;end loop;
 for target in select (x#>>'{}')::int from ml_private.arr(pending->'elbows') x loop if not ml_private.stage3_alive(s,target) then continue;end if;amount:=(s#>>array['players',a::text,'ap'])::int;if amount=0 then hits:=hits||jsonb_build_array(jsonb_build_object('target',a,'amount',1,'source',target,'category','response'));else amount:=least(2,amount);s:=jsonb_set(s,array['players',a::text,'ap'],to_jsonb((s#>>array['players',a::text,'ap'])::int-amount));s:=ml_private.stage3_gain_ap(s,target,amount);s:=s-'_gain';end if;end loop;
 s:=ml_private.damage(s,hits);after_tasks:=s->'_triggers';s:=s-'_triggers';if pending->>'definition'='basic-006' and ml_private.stage3_alive(s,a) then select coalesce(sum((before_hp->>(x#>>'{}')::int)::int-(s#>>array['players',x#>>'{}','hp'])::int),0)::int into amount from ml_private.arr(targets) x;s:=ml_private.heal(s,a,amount);end if;
 if jsonb_array_length(ledger)>0 and xie is not null then after_tasks:=after_tasks||jsonb_build_array(ml_private.stage3_task('ledger',jsonb_build_object('actor',xie,'data',ledger)));end if;
 elsif d->>'type'='food' then for target in select (x#>>'{}')::int from ml_private.arr(targets) x loop s:=ml_private.heal(s,target,case when pending->>'definition'='basic-046' then 2 else 1 end,true);if pending->>'definition'='basic-045' then s:=jsonb_set(s,array['players',target::text,'shield'],to_jsonb(least(2,(s#>>array['players',target::text,'shield'])::int+1)));end if;if pending->>'definition'='basic-047' then s:=ml_private.draw(s,target,2);end if;end loop;
 elsif pending->>'definition'='basic-015' then for target in select (x#>>'{}')::int from ml_private.arr(targets) x loop s:=ml_private.stage3_coffee(s,target);s:=ml_private.emit(s,'ap','S'||(target+1)||' 咖啡获得'||(s#>>'{_gain,gained}')||'AP，晓虫收取'||(s#>>'{_gain,taken}')||'AP');s:=s-'_gain';end loop;
 elsif pending->>'definition'='basic-016' then for target in select (x#>>'{}')::int from ml_private.arr(targets) x loop if not ml_private.stage3_card_allowed(s,a,pending->>'definition',pending->'effect') or not ml_private.stage3_can_enter(s,a,s#>>array['players',target::text,'cell']) or not ml_private.stage3_can_enter(s,target,s#>>array['players',a::text,'cell']) then continue;end if;origin:=s#>>array['players',a::text,'cell'];old:=s#>>array['players',target::text,'cell'];s:=ml_private.stage3_relocate(s,a,old,true);after_tasks:=after_tasks||(s->'_relocationTasks');s:=s-'_relocationTasks';s:=ml_private.stage3_relocate(s,target,origin,false);after_tasks:=after_tasks||(s->'_relocationTasks');s:=s-'_relocationTasks';end loop;
 elsif pending->>'definition'='basic-037' then for target in select (x#>>'{}')::int from ml_private.arr(pending->'targets') x loop if not ml_private.stage3_card_allowed(s,target,pending->>'definition',pending->'effect') then continue;end if;cells:=ml_private.stage3_revival_cells(s,target,(s#>>'{classic,farmClosed}')::boolean);if jsonb_array_length(cells)=0 then continue;end if;s:=ml_private.int(s,jsonb_array_length(cells));old:=cells->>(s->>'_int')::int;s:=s-'_int';s:=ml_private.stage3_revive(s,target,old,(s#>>'{classic,farmClosed}')::boolean);s:=jsonb_set(s,array['classic','exposure',target::text],jsonb_build_object('region',null,'streak',0));s:=jsonb_set(s,array['classic','caveEnds',target::text],'0');s:=ml_private.emit(s,'revive','S'||(target+1)||' 紫檀木复活于'||old||'：1HP、0AP、空手');end loop;
 elsif d->>'type'='equipment' then
 if pending ? 'replacement' then old:=pending->>'replacement';old_source:=s#>array['stage3','equipmentSources',old];s:=jsonb_set(s,array['stage3','equipment',a::text],(s#>array['stage3','equipment',a::text])-old);s:=jsonb_set(s,'{stage3,equipmentSources}',(s#>'{stage3,equipmentSources}')-old);s:=jsonb_set(s,'{discard}',(s->'discard')||jsonb_build_array(old));if old_source is not null and ml_private.stage3_card_allowed(s,a,old,old_source||jsonb_build_object('origin','equipment')) then cells:=null;if split_part(old,'#',1)='basic-063' then select coalesce(jsonb_agg(cell->'id' order by ord),'[]') into cells from jsonb_array_elements(ml_private.game_data(s,'cells')) with ordinality q(cell,ord) where cell->>'region'='山洞' and ml_private.stage3_empty_entry(ml_private.stage3_board(s),a,cell->>'id');end if;if split_part(old,'#',1)='basic-054' or jsonb_array_length(cells)>0 then s:=ml_private.select_choice(s,'equipment-loss',a,at,jsonb_build_object('data',jsonb_build_object('card',old))||case when cells is null then '{}'::jsonb else jsonb_build_object('cells',cells) end);end if;end if;end if;after_tasks:=after_tasks||jsonb_build_array(ml_private.stage3_task('equip-install',jsonb_build_object('serial',pending->'serial')));
 end if;return ml_private.stage3_prepend(s,after_tasks||jsonb_build_array(ml_private.stage3_task('cleanup',jsonb_build_object('serial',pending->'serial'))));
end $$;
create or replace function ml_private.targets(s jsonb,a integer,card text) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$ declare d jsonb:=ml_private.rule_card(s,card);p jsonb:=s->'players'->a;result jsonb;lemon integer;begin
 if s->>'version'<>'web-v0.1.6' then return ml_private.targets_before_stage3(s,a,card);end if;
 if d is null or d->>'type'<>'attack' then return '[]';end if;if d->>'id'='basic-010' then return ml_private.stage3_monkey_targets(s,a);end if;
 select coalesce(jsonb_agg(q->'seat' order by ord),'[]') into result from jsonb_array_elements(s->'players') with ordinality t(q,ord) where (q->>'hp')::int>0 and (q->>'seat')::int<>a and (s->>'mode'='ffa' or q->'team'<>p->'team') and not (d->>'group'='true' and q->>'character'='character-027' and jsonb_array_length(q->'hand')=1) and ml_private.location_card_allowed(s->>'version',p->>'cell',d->>'id') and (d->>'range'='global' or ml_private.game_data(s,'map')#>>array[q->>'cell','region']=ml_private.game_data(s,'map')#>>array[p->>'cell','region'] or (d->>'range'='adjacent' and ml_private.stage3_same_near(p->>'cell',q->>'cell')));
 select (q->>'seat')::int into lemon from ml_private.arr(s->'players') q where q->>'character'='character-004' and result @> jsonb_build_array(q->'seat');if coalesce(d->>'group','false')<>'true' and lemon is not null then return jsonb_build_array(lemon);end if;return result;
end $$;
create or replace function ml_private.legal_steps(s jsonb) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$ declare result jsonb:='[]';c jsonb;a integer:=(s->>'active')::int;p jsonb:=s->'players'->a;cost integer;target integer;valid boolean;begin
 if s->>'version'<>'web-v0.1.6' then return ml_private.legal_steps_before_stage3(s);end if;
 if s->>'phase'<>'moving' or s->'movement'='null'::jsonb then return result;end if;
 for c in select * from ml_private.arr(ml_private.game_data(s,'cells')) loop cost:=ml_private.classic_step_cost(s,a,c->>'id');
 if not ml_private.stage3_can_enter(s,a,c->>'id') or (s#>>'{movement,direction}' is not null and not ml_private.stage3_west_step(p->>'cell',c->>'id',s#>>'{movement,direction}')) then continue;end if;
 select (q->>'seat')::int into target from ml_private.arr(s->'players') q where (q->>'hp')::int>0 and (q->>'seat')::int<>a and q->'cell'=c->'id' limit 1;
 if target is not null and p->>'character'='character-040' then continue;end if;
 if target is not null and p->>'character'='character-045' then valid:=cost is not null and cost<=(s#>>'{movement,remaining}')::int and not ml_private.location_stops(s->>'version',c->>'id') and jsonb_array_length(ml_private.stage3_collision_path(ml_private.stage3_board(s),a,target,ml_private.stage3_direction(s,p->>'cell',c->>'id')))>0;
 else valid:=cost is not null and cost<=(s#>>'{movement,remaining}')::int and ml_private.escape(s,a,c->>'id',(s#>>'{movement,remaining}')::int-cost);end if;
 if valid then result:=result||jsonb_build_array(c->'id');end if;end loop;return result;
end $$;
create or replace function ml_private.teleport_cells(s jsonb,a integer) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$ begin
 if s->>'version'='web-v0.1.6' and ml_private.stage3_mount_blocked(s,a) then return '[]';end if;return ml_private.teleport_cells_before_stage3(s,a);
end $$;
create or replace function ml_private.settle_movement(s jsonb) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare m jsonb:=s->'movement';begin
 if s->>'version'='web-v0.1.6' and jsonb_array_length(m->'path')>1 and jsonb_array_length(coalesce(m->'carry','[]'))>0 then s:=ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('carry',jsonb_build_object('actor',s->'active','data',m->'carry'))));s:=jsonb_set(s,'{movement,carry}','[]');end if;return ml_private.settle_movement_before_stage3(s);
end $$;
create or replace function ml_private.classic_walk(s jsonb,path jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare a integer:=(s->>'active')::int;p jsonb;m jsonb;check_s jsonb;cell text;origin text;cost integer;idx integer:=0;pushed jsonb;tail jsonb;begin
 if s->>'version'<>'web-v0.1.6' then return ml_private.classic_walk_before_stage3(s,path,at);end if;
 s:=jsonb_set(s,'{phase}','"moving"');check_s:=s;
 for cell in select x#>>'{}' from ml_private.arr(path) x loop perform ml_private.need(ml_private.legal_steps(check_s) ? cell,'移动路径不合法：检查步数、占用、封闭地区或越水落点');check_s:=ml_private.stage3_collision(check_s,cell);check_s:=check_s-'_pushedTasks';cost:=ml_private.classic_step_cost(check_s,a,cell);check_s:=jsonb_set(check_s,'{movement,remaining}',to_jsonb((check_s#>>'{movement,remaining}')::int-cost));check_s:=jsonb_set(check_s,array['players',a::text,'cell'],to_jsonb(cell));if ml_private.location_stops(check_s->>'version',cell) then check_s:=jsonb_set(check_s,'{movement,remaining}','0');end if;end loop;
 for cell in select x#>>'{}' from ml_private.arr(path) x loop perform ml_private.need(ml_private.legal_steps(s) ? cell,'移动路径不合法：检查步数、占用、封闭地区或越水落点');s:=ml_private.stage3_collision(s,cell);pushed:=s->'_pushedTasks';s:=s-'_pushedTasks';p:=s->'players'->a;m:=s->'movement';origin:=p->>'cell';cost:=ml_private.classic_step_cost(s,a,cell);
 m:=m||jsonb_build_object('remaining',(m->>'remaining')::int-cost,'path',(m->'path')||jsonb_build_array(cell));p:=p||jsonb_build_object('cell',cell);s:=ml_private.put_player(s,a,p);s:=ml_private.classic_relocated(s,a,origin,cell);s:=jsonb_set(s,array['stage3','voluntaryMoved',a::text],'true');if not ml_private.occupied(s,cell,a) then m:=m||jsonb_build_object('lastEmpty',cell);end if;if ml_private.location_stops(s->>'version',cell) then m:=jsonb_set(m,'{remaining}','0');end if;s:=jsonb_set(s,'{movement}',m);s:=ml_private.emit(s,'move',ml_private.name(s,a)||' → '||cell||'，消耗'||cost||'步，余'||(m->>'remaining'));idx:=idx+1;
 select coalesce(jsonb_agg(x order by n),'[]') into tail from jsonb_array_elements(path) with ordinality t(x,n) where n>idx;
 if jsonb_array_length(pushed)>0 then s:=ml_private.stage3_prepend(s,pushed||jsonb_build_array(jsonb_build_object('kind','walk','path',tail)));return jsonb_set(s,'{phase}','"resolving"');end if;
 if ml_private.classic_owes_water(s,a,origin) then s:=ml_private.stage3_prepend(s,jsonb_build_array(jsonb_build_object('kind','walk','path',tail)));return ml_private.select_choice(s,'water-discard',a,at,jsonb_build_object('count',1,'cards',p->'hand'));end if;end loop;
 if (s#>>'{movement,remaining}')::int=0 then s:=ml_private.settle_movement(s);s:=s||jsonb_build_object('movement',null,'phase','action');end if;return ml_private.resume(s,at);
end $$;
create or replace function ml_private.stage3_locations(s jsonb,a integer,kind text) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$ declare input jsonb;result jsonb;begin
 if ml_private.stage3_mount_blocked(s,a) then return '[]';end if;
 input:=ml_private.stage3_board(s)||jsonb_build_object('shipUsed',s#>'{classic,shipUsed}');if kind='ship' and s#>>array['stage3','jjFree',a::text]='true' then input:=jsonb_set(input,array['players',a::text,'ap'],to_jsonb(greatest(1,(s#>>array['players',a::text,'ap'])::int)));end if;
 select coalesce(jsonb_agg(c order by ord),'[]') into result from jsonb_array_elements(ml_private.location_destinations(input,a,kind)) with ordinality t(c,ord) where ml_private.stage3_can_enter(s,a,c#>>'{}');return result;
end $$;
create or replace function ml_private.stage3_play(s jsonb,cmd jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare a integer:=(cmd->>'actor')::int;p jsonb:=s->'players'->a;card text:=cmd->>'card';d jsonb:=ml_private.rule_card(s,card);converted boolean:=coalesce(cmd->>'as','')='elbow';elbow boolean;boost boolean;quoted jsonb;effect jsonb;targets jsonb:=cmd->'targets';legal jsonb;cells jsonb;options jsonb;exposed jsonb;pending jsonb;idx text;cost integer;begin
 perform ml_private.need(p->'hand' ? card and d is not null,'手中没有该实体牌');perform ml_private.need(s#>>array['stage3','breadBlocked',a::text]<>'true','面包：本个人回合不能主动出牌');elbow:=p->>'character'='character-023' and (converted or d->>'id'='basic-002');perform ml_private.need(not converted or p->>'character'='character-023','只有牢大可以转换肘击');perform ml_private.need(d->>'type'<>'response' or elbow,'响应牌只能在相应窗口使用');
 perform ml_private.need(p->>'character'<>'character-005' or converted or not (ml_private.version_catalog('web-v0.1.5')#>array['sourceCatalog','cards',d->>'id','tags'] ? '建民'),'QB不能使用建民牌');boost:=p->>'character'='character-045' and d->>'id'='basic-010';perform ml_private.need(boost or converted or ml_private.location_card_allowed(s->>'version',p->>'cell',d->>'id'),'当前位置禁止使用此牌');
 if converted then quoted:=jsonb_build_object('cost',ml_private.stage3_fixed_cost(s,a,2),'effect',jsonb_build_object('origin','role-active','actor',a,'faction',p->'faction','roleModifiers',jsonb_build_array(jsonb_build_object('actor',a,'kind','conversion'))));
 else quoted:=ml_private.stage3_card_cost(s,a,card,case when s#>array['stage3','costLocks',card,'turn']=s#>'{stage3,turn}' then (s#>>array['stage3','costLocks',card,'cost'])::int else null end);end if;effect:=quoted->'effect';
 if elbow and not converted then effect:=jsonb_set(effect,'{roleModifiers}',(effect->'roleModifiers')||jsonb_build_array(jsonb_build_object('actor',a,'kind','other')));end if;if boost then effect:=jsonb_set(effect,'{roleModifiers}',(effect->'roleModifiers')||jsonb_build_array(jsonb_build_object('actor',a,'kind','target')));end if;cost:=(quoted->>'cost')::int;
 perform ml_private.need((p->>'ap')::int>=cost,'需要'||cost||'AP');perform ml_private.need((select count(distinct x) from ml_private.arr(targets) x)=jsonb_array_length(targets),'目标不能重复');
 if elbow then perform ml_private.need(jsonb_array_length(targets)=1 and ml_private.stage3_elbow_targets(s,a,converted) @> targets,'主动肘击目标不合法');
 elsif d->>'type'='attack' then legal:=ml_private.targets(s,a,card);perform ml_private.need(jsonb_array_length(targets) between 1 and case when d->>'group'='true' then 3 else 1 end and legal @> targets,'攻击目标不合法');
 elsif d->>'id'='basic-016' then perform ml_private.need(jsonb_array_length(targets)=1 and (targets->>0)::int<>a and ml_private.stage3_alive(s,(targets->>0)::int) and not ml_private.stage3_mount_blocked(s,a) and ml_private.stage3_empty_entry(ml_private.stage3_board(s),a,s#>>array['players',targets->>0,'cell'],jsonb_build_array(a,targets->0)) and ml_private.stage3_empty_entry(ml_private.stage3_board(s),(targets->>0)::int,p->>'cell',jsonb_build_array(a,targets->0)),'交换目标或坐骑位移限制不合法');
 elsif d->>'id'='basic-037' then perform ml_private.need(jsonb_array_length(targets)=1 and jsonb_array_length(ml_private.stage3_revival_cells(s,(targets->>0)::int,(s#>>'{classic,farmClosed}')::boolean))>0,'当前没有合法复活目标');
 else perform ml_private.need(targets='[]'::jsonb,'此牌不接受外部目标');targets:=case when d->>'id'='basic-041' then ml_private.stage3_assam_targets(s,a) else jsonb_build_array(a) end;end if;
 if not converted and d->>'type'='equipment' then options:=ml_private.stage3_equipment_options(s,a,card);perform ml_private.need(options->>'allowed'='true' and (options->>'required'<>'true' or cmd ? 'replacement') and (not (cmd ? 'replacement') or options->'cards' ? (cmd->>'replacement')),'请先选择合法装备替换对象');perform ml_private.need(d->>'id'<>'basic-063' or ml_private.game_data(s,'map')#>>array[p->>'cell','terrain']<>'water','水中不能装备禁水的哈基米');end if;
 if elbow then cells:=ml_private.stage3_elbow_cells(ml_private.stage3_board(s),a,(targets->>0)::int);perform ml_private.need(jsonb_array_length(cells)=0 or (cmd ? 'direction') and cells ? ml_private.stage3_direction_cell(s#>>array['players',targets->>0,'cell'],cmd->>'direction'),'请先选择合法撞飞方向');end if;exposed:=ml_private.stage3_jj_targets(s,a,case when elbow then 'basic-002' else card end,targets,effect);targets:=exposed->'targets';effect:=exposed->'effect';p:=p||jsonb_build_object('ap',(p->>'ap')::int-cost,'hand',(p->'hand')-card);if d->>'type'='attack' or elbow then p:=p||jsonb_build_object('attacks',(p->>'attacks')::int+1);end if;s:=ml_private.put_player(s,a,p);s:=s||jsonb_build_object('resolving',(s->'resolving')||jsonb_build_array(card),'clock',jsonb_build_object('remaining',60000,'since',at));
 s:=ml_private.stage3_begin_card(s,a,card,case when elbow then 'basic-002' else d->>'id' end,targets,effect,at);pending:=s#>'{cardStack,stack,-1}';if elbow then pending:=pending||jsonb_build_object('converted',converted);if cmd ? 'direction' then pending:=pending||jsonb_build_object('pushDirection',cmd->'direction');end if;end if;if cmd ? 'replacement' then pending:=pending||jsonb_build_object('replacement',cmd->'replacement');end if;idx:=(jsonb_array_length(s#>'{cardStack,stack}')-1)::text;s:=jsonb_set(s,array['cardStack','stack',idx],pending);
 s:=ml_private.emit(s,'play','S'||(a+1)||' 使用'||case when elbow then '肘击' else d->>'name' end||'，支付'||cost||'AP',jsonb_build_object('actor',a,'card',card,'targets',targets));s:=jsonb_set(s,'{phase}','"resolving"');return ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('counter',jsonb_build_object('serial',pending->'serial')),ml_private.stage3_task('continue',jsonb_build_object('serial',pending->'serial'))));
end $$;
create or replace function ml_private.stage3_board(s jsonb) returns jsonb language sql immutable as $$ select s||jsonb_build_object('farmClosed',s#>'{classic,farmClosed}') $$;
create or replace function ml_private.stage3_task(action text,extra jsonb default '{}') returns jsonb language sql immutable as $$ select jsonb_build_object('kind','stage3','action',action)||extra $$;
create or replace function ml_private.stage3_prepend(s jsonb,tasks jsonb) returns jsonb language sql immutable as $$ select jsonb_set(s,'{queue}',tasks||(s->'queue')) $$;
create or replace function ml_private.stage3_fixed_cost(s jsonb,a integer,amount integer) returns integer language sql immutable as $$ select case when amount>0 and s#>>array['stage3','jjFree',a::text]='true' then 0 else amount end $$;
create or replace function ml_private.damage(s jsonb,hits jsonb,environment boolean default false) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ begin
 if s->>'version'='web-v0.1.6' then return ml_private.stage3_damage(s,hits,environment,false);end if;return ml_private.damage_before_stage3(s,hits,environment);
end $$;
create or replace function ml_private.pump(s jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare t jsonb;a integer;p jsonb;due jsonb;guard integer:=0;allowed boolean;ap integer;countn integer;cells jsonb;cursor integer;kind text;begin
 if s->>'version'<>'web-v0.1.6' then return ml_private.pump_before_stage3(s,at);end if;
 while s->'choice'='null'::jsonb and s->>'phase'<>'over' loop
 due:=ml_private.stage3_overflow(s,s->'order')->0;
 if due is not null then a:=(due->>'actor')::int;s:=ml_private.select_choice(s,'xiao-overflow',a,at,jsonb_build_object('source',due->'collector','count',due->'count','cards',s#>array['players',a::text,'hand']));exit;end if;
 exit when jsonb_array_length(s->'queue')=0;guard:=guard+1;perform ml_private.need(guard<200,'内部流程未收敛');t:=s->'queue'->0;s:=jsonb_set(s,'{queue}',(s->'queue')-0);a:=coalesce((t->>'actor')::int,(s->>'active')::int);p:=s->'players'->a;
 case t->>'kind'
 when 'stage3' then s:=ml_private.stage3_handle_task(s,t,at);if s->>'phase'='action' and s->'choice'='null'::jsonb then s:=ml_private.resume(s,at);end if;
 when 'water' then if ml_private.classic_owes_water(s,a) or (t#>>'{data,entry}'='true' and (p->>'hp')::int>0 and jsonb_array_length(p->'hand')>0) then s:=ml_private.select_choice(s,'water-discard',a,at,jsonb_build_object('count',1,'cards',p->'hand'));end if;
 when 'classic-start' then
 for a in 0..3 loop p:=s->'players'->a;if (p->>'hp')::int>0 then p:=p||jsonb_build_object('skillUsed',false,'rewarded','[]'::jsonb);s:=ml_private.put_player(s,a,p);s:=ml_private.stage3_round_gain_allowed(s,a);allowed:=(s->>'_allowed')::boolean;s:=s-'_allowed';
 if allowed and (p->>'ap')::int<5 and p->>'character'<>'character-031' then s:=ml_private.stage3_gain_ap(s,a,3);s:=s-'_gain';s:=ml_private.emit(s,'ap',ml_private.name(s,a)||' 轮开始获得3AP → '||(s#>>array['players',a::text,'ap']));end if;end if;end loop;
 s:=ml_private.classic_refresh(s);s:=ml_private.emit(s,'round','第'||(s->>'round')||'轮开始，毒区：'||(select string_agg(x#>>'{}','、') from ml_private.arr(s#>'{classic,poison}') x)||case when s#>>'{classic,farmClosed}'='true' then '；高唐农场已封闭' else '' end);s:=ml_private.stage3_prepend(s,jsonb_build_array(jsonb_build_object('kind','after-env')));
 when 'round-next' then s:=ml_private.finish(s,false,at);if s->>'phase'<>'over' then s:=s||jsonb_build_object('round',(s->>'round')::int+1,'cursor',0);s:=ml_private.start_round(s,at);end if;
 when 'walk' then s:=ml_private.classic_walk(s,coalesce(t->'path','[]'),at);
 when 'after-env' then s:=ml_private.finish(s,false,at);if s->>'phase'<>'over' then cursor:=0;while not ml_private.stage3_alive(s,(s->'order'->>cursor)::int) loop cursor:=cursor+1;end loop;s:=s||jsonb_build_object('cursor',cursor);s:=ml_private.stage3_prepend(s,jsonb_build_array(jsonb_build_object('kind','turn-start','actor',s->'order'->cursor)));end if;
 when 'turn-start' then
 s:=jsonb_set(s,'{classic,shipUsed}',(select coalesce(jsonb_agg(x),'[]') from ml_private.arr(s#>'{classic,shipUsed}') x where x<>to_jsonb(a)));
 s:=s||jsonb_build_object('active',a,'phase','resolving','clock',jsonb_build_object('remaining',60000,'since',at));s:=ml_private.put_player(s,a,p||jsonb_build_object('moved',false,'attacks',0));s:=ml_private.stage3_turn_start(s,a);s:=ml_private.stage3_start_gain_allowed(s,a);allowed:=(s->>'_allowed')::boolean;s:=s-'_allowed';p:=s->'players'->a;
 if allowed and p->>'character'='character-031' and (p->>'ap')::int<6 then p:=p||jsonb_build_object('ap',6);s:=ml_private.put_player(s,a,p);s:=ml_private.emit(s,'ap',ml_private.name(s,a)||' 行动开始补至6AP');end if;
 ap:=case when allowed then ml_private.location_personal_ap(s->>'version',p,(s->>'round')::int) else (p->>'ap')::int end;
 if ap>(p->>'ap')::int then s:=ml_private.stage3_gain_ap(s,a,ap-(p->>'ap')::int);s:=s-'_gain';s:=ml_private.emit(s,'ap',ml_private.name(s,a)||' 尚德荟获得1AP → '||(s#>>array['players',a::text,'ap']));end if;
 s:=ml_private.emit(s,'turn',ml_private.name(s,a)||' 开始行动');if (s->>'round')::int>1 then s:=ml_private.draw(s,a,ml_private.location_draw_count(s->>'version',p->>'cell',(s->>'round')::int));end if;
 s:=ml_private.stage3_prepend(s,case when p->>'character'='character-010' then jsonb_build_array(ml_private.stage3_task('east',jsonb_build_object('actor',a))) else '[]'::jsonb end||jsonb_build_array(jsonb_build_object('kind','action')));if p->>'character'='character-027' then s:=ml_private.select_choice(s,'draw-start',a,at);end if;
 when 'action' then s:=jsonb_set(s,'{phase}','"action"');s:=ml_private.resume(s,at);
 when 'end-draw' then s:=ml_private.stage3_prepend(s,jsonb_build_array(jsonb_build_object('kind','cave-end')));if p->>'character'='character-027' and (p->>'hp')::int>0 and ml_private.budget(s,at)>0 then s:=ml_private.select_choice(s,'draw-end',a,at);end if;
 when 'cave-end' then s:=ml_private.cave_ending(s,a);if jsonb_array_length(s->'_hits')>0 then s:=ml_private.damage(s,s->'_hits',true);s:=ml_private.stage3_prepend(s,(s->'_triggers')||jsonb_build_array(jsonb_build_object('kind','cave-after','actor',a)));s:=s-'_triggers';else s:=ml_private.stage3_prepend(s,jsonb_build_array(jsonb_build_object('kind','cave-after','actor',a)));end if;s:=s-'_hits';
 when 'cave-after' then s:=ml_private.finish(s,false,at);if s->>'phase'<>'over' then s:=ml_private.stage3_prepend(s,jsonb_build_array(jsonb_build_object('kind','discard','actor',a)));end if;
 when 'discard' then countn:=jsonb_array_length(p->'hand')-(p->>'hp')::int;s:=ml_private.stage3_prepend(s,jsonb_build_array(jsonb_build_object('kind','next')));if (p->>'hp')::int>0 and countn>0 then s:=ml_private.select_choice(s,'discard',a,at,jsonb_build_object('count',countn,'cards',p->'hand'));end if;
 when 'next' then s:=ml_private.next_turn(s,at);
 when 'trigger' then
 if (p->>'hp')::int<=0 then continue;end if;kind:=t->>'trigger';
 if kind='lemon-reward' then if t ? 'source' and not (s#>array['players',t->>'source','rewarded'] @> jsonb_build_array(a)) then s:=ml_private.select_choice(s,kind,a,at,jsonb_build_object('source',t->'source'));end if;
 elsif p->>'skillUsed'='false' then
 if (kind='lemon-support' and (p->>'ap')::int>=1) or (kind='runner-roll' and (p->>'ap')::int>=2) then s:=ml_private.select_choice(s,kind,a,at);end if;
 if kind='teleport' then cells:=ml_private.teleport_cells(s,a);if jsonb_array_length(cells)>0 then s:=ml_private.select_choice(s,kind,a,at,jsonb_build_object('cells',cells));end if;end if;end if;
 else raise exception '未知内部任务';end case;end loop;return s;
end $$;
create or replace function ml_private.validate(s jsonb) returns void language plpgsql stable set search_path=pg_catalog,ml_private as $$ declare p jsonb; zones jsonb; a integer;b integer;begin
 if s->>'version'<>'web-v0.1.6' then perform ml_private.validate_before_stage3(s);return;end if;
 perform ml_private.need(jsonb_array_length(s->'players')=4 and (s->>'round')::int>=1 and (select jsonb_agg(x order by x) from ml_private.arr(s->'order') x)='[0,1,2,3]'::jsonb,'状态版本/轮次/人数无效');
 perform ml_private.need((select count(distinct member->>'character') from ml_private.arr(s->'players') member)=4 and not exists(select 1 from ml_private.arr(s->'players') member where not (ml_private.game_data(s,'characterIds') ? (member->>'character'))),'角色/顺序无效');
 zones:=(s->'deck')||(s->'discard')||(s->'resolving');
 for a in 0..3 loop p:=s->'players'->a;zones:=zones||(p->'hand')||(s#>array['stage3','equipment',a::text]);
 perform ml_private.need((p->>'hp')::numeric=trunc((p->>'hp')::numeric) and (p->>'hp')::int between 0 and (p->>'maxHp')::int and p->'maxHp'=ml_private.game_data(s,'characters')->(p->>'character')->'hp','生命状态无效');
 perform ml_private.need((p->>'ap')::numeric=trunc((p->>'ap')::numeric) and (p->>'ap')::int>=0 and (p->>'shield')::int between 0 and 2,'AP/护盾无效');perform ml_private.need(ml_private.game_data(s,'map') ? (p->>'cell'),'位置无效');
 if (p->>'hp')::int=0 then perform ml_private.need((p->>'ap')::int=0 and (p->>'shield')::int=0 and p->'hand'='[]'::jsonb and p->'eliminated'<>'null'::jsonb and s#>array['stage3','equipment',a::text]='[]'::jsonb,'淘汰清理无效');end if;
 for b in 0..a-1 loop if ml_private.stage3_alive(s,a) and ml_private.stage3_alive(s,b) and p->'cell'=s->'players'->b->'cell' then perform ml_private.need((s->>'phase'='moving' or s#>>'{choice,kind}'='water-discard') and s->'movement'<>'null'::jsonb,'稳定落点不能重叠');end if;end loop;end loop;
 perform ml_private.need((select jsonb_agg(x order by x) from ml_private.arr(zones) x)=(select jsonb_agg(x order by x) from ml_private.arr(ml_private.game_data(s,'allCards')) x),'实体不守恒或实体重复');
 perform ml_private.need(jsonb_array_length(s#>'{classic,caveEnds}')=4 and not exists(select 1 from ml_private.arr(s#>'{classic,caveEnds}') n where (n#>>'{}')::int not between 0 and 2),'山洞计数无效');
 perform ml_private.need((s#>>'{clock,remaining}')::double precision>=0,'计时预算无效');
end $$;
create or replace function ml_private.finish(s jsonb,forced boolean,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare combos jsonb;result_state jsonb;rows jsonb;winners jsonb;last_idx text;result jsonb;tied boolean;begin
 result_state:=ml_private.finish_before_stage3(s,forced,at);if s->>'version'<>'web-v0.1.6' or result_state->>'phase'='over' then return result_state;end if;
 combos:=ml_private.stage3_combo_teams(s);if jsonb_array_length(combos)=0 then return s;end if;
 result_state:=ml_private.finish_before_stage3(s,true,at);rows:=result_state#>'{result,ranking}';tied:=jsonb_array_length(combos)>1;
 if not tied then
 select jsonb_agg(r order by winning desc,ord) into rows from (select r,ord,combos ? (s#>>array['players',r#>>'{players,0}','team']) winning from jsonb_array_elements(rows) with ordinality t(r,ord)) q;
 select jsonb_agg(r||jsonb_build_object('rank',ord) order by ord) into rows from jsonb_array_elements(rows) with ordinality t(r,ord);
 select jsonb_agg(p->'seat' order by ord) into winners from jsonb_array_elements(s->'players') with ordinality t(p,ord) where combos ? (p->>'team');else winners:='[]';end if;
 result:=jsonb_build_object('reason',case when tied then 'draw' else 'combo' end,'winners',winners,'ranking',rows);last_idx:=(jsonb_array_length(result_state->'events')-1)::text;
 result_state:=jsonb_set(result_state,'{result}',result);result_state:=jsonb_set(result_state,array['events',last_idx,'data'],result);
 return jsonb_set(result_state,array['events',last_idx,'text'],to_jsonb(case when tied then '对局结束：平局' else '对局结束：'||(rows->0->>'label')||' 获胜' end));
end $$;
create or replace function ml_private.stage3_relocate(s jsonb,a integer,cell text,voluntary boolean,carry boolean default true) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare origin text:=s#>>array['players',a::text,'cell']; snapshots jsonb; tasks jsonb:='[]';begin
 if origin=cell or voluntary and ml_private.stage3_mount_blocked(s,a) then return s||jsonb_build_object('_relocationTasks',tasks);end if;
 snapshots:=case when carry then ml_private.stage3_carry_candidates(s,a,origin) else '[]'::jsonb end;
 s:=ml_private.classic_relocated(s,a,origin,cell);s:=jsonb_set(s,array['players',a::text,'cell'],to_jsonb(cell));if voluntary then s:=jsonb_set(s,array['stage3','voluntaryMoved',a::text],'true');end if;s:=ml_private.emit(s,'move',ml_private.name(s,a)||' → '||cell);
 if ml_private.classic_owes_water(s,a,origin) then tasks:=tasks||jsonb_build_array(jsonb_build_object('kind','water','actor',a,'data',jsonb_build_object('entry',true)));end if;
 if jsonb_array_length(snapshots)>0 then tasks:=tasks||jsonb_build_array(ml_private.stage3_task('carry',jsonb_build_object('actor',a,'data',snapshots)));end if;
 return s||jsonb_build_object('_relocationTasks',tasks);
end $$;
create or replace function ml_private.stage3_direction(s jsonb,origin text,cell text) returns text language sql stable set search_path=pg_catalog,ml_private as $$ select case when ml_private.game_data(s,'map')#>array[origin,'row']=ml_private.game_data(s,'map')#>array[cell,'row'] then case when (ml_private.game_data(s,'map')#>>array[cell,'col'])::int>(ml_private.game_data(s,'map')#>>array[origin,'col'])::int then 'right' else 'left' end else case when (ml_private.game_data(s,'map')#>>array[cell,'row'])::int>(ml_private.game_data(s,'map')#>>array[origin,'row'])::int then 'down' else 'up' end end $$;
create or replace function ml_private.stage3_collision(s jsonb,cell text) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare a integer:=(s->>'active')::int;target integer;path jsonb;snapshots jsonb;tasks jsonb:='[]';c jsonb;begin
 select (p->>'seat')::int into target from ml_private.arr(s->'players') p where (p->>'hp')::int>0 and (p->>'seat')::int<>a and p->>'cell'=cell limit 1;
 if target is null or s#>>array['players',a::text,'character']<>'character-045' then return s||jsonb_build_object('_pushedTasks',tasks);end if;
 path:=ml_private.stage3_collision_path(ml_private.stage3_board(s),a,target,ml_private.stage3_direction(s,s#>>array['players',a::text,'cell'],cell));perform ml_private.need(jsonb_array_length(path)>0,'角色或地形阻挡冲撞');snapshots:=ml_private.stage3_carry_candidates(s,target,s#>>array['players',target::text,'cell']);
 for c in select * from ml_private.arr(path) loop s:=ml_private.stage3_relocate(s,target,c#>>'{}',false,false);tasks:=tasks||(s->'_relocationTasks');s:=s-'_relocationTasks';end loop;
 if jsonb_array_length(snapshots)>0 then tasks:=tasks||jsonb_build_array(ml_private.stage3_task('carry',jsonb_build_object('actor',target,'data',snapshots)));end if;return s||jsonb_build_object('_pushedTasks',tasks);
end $$;
